   black border       → PlaneGeometry(PW+0.05, PH+0.05)  #111
   window tile        → PlaneGeometry(w,h) + per-tile UV window, MeshBasic(map)
   token grid         → LineSegments  #3a3a3a  (8x8 lines, clipped per tile)
   tile outline       → LineSegments  #2a2a2a
   selected frame     → PlaneGeometry (tile + 0.07)  #ff9d2e
   neighbour frame    → PlaneGeometry (tile + 0.07)  #2e8bff
   attention lines    → LineSegments  #ff9d2e a=.35 / #2e8bff a=.30
   regular seams      → LineSegments dashed  #c03cc0
   panel letter, caption → addLabel
──────────────────────────────────────────────────────────────────────────── */

const PW = 3.45, PH = 3.0, PSI = 0.85;   // plane size (local) + yaw
const GAP_U = 0.062 / PW, GAP_V = 0.055 / PH;
const NTOK = 8;

/* ── mural texture (procedurally painted, not a pasted photo) ───────────── */
function makeMural() {
  const cw = 512, ch = 480;
  const cv = document.createElement('canvas'); cv.width = cw; cv.height = ch;
  const g = cv.getContext('2d');
  const X = u => u * cw, Y = v => v * ch;

  g.fillStyle = '#b6b8bb'; g.fillRect(0, 0, cw, ch);
  for (let i = 0; i < 80; i++) {
    g.globalAlpha = 0.16; g.fillStyle = (i % 2) ? '#a7a9ac' : '#c6c8cb';
    g.fillRect((i * 97 % cw), Y(0.12), 3 + (i * 31 % 13), Y(0.2) + (i * 53 % 200));
  }
  g.globalAlpha = 1;

  // sky + foliage strip
  g.fillStyle = '#9ec4dd'; g.fillRect(0, 0, cw, Y(0.075));
  g.fillStyle = '#6f8a3c';
  for (let i = 0; i <= 26; i++) { g.beginPath(); g.arc(i * cw / 26, Y(0.035) + ((i * 37) % 3) * 5, 14 + ((i * 13) % 5) * 3, 0, Math.PI * 2); g.fill(); }
  g.fillStyle = '#55702c';
  for (let i = 0; i <= 20; i++) { g.beginPath(); g.arc(i * cw / 20 + 9, Y(0.018) + ((i * 29) % 4) * 4, 9 + ((i * 7) % 4) * 3, 0, Math.PI * 2); g.fill(); }
  // ochre wall trim
  g.fillStyle = '#b89a3c'; g.fillRect(0, Y(0.072), cw, Y(0.035));
  g.fillStyle = '#6d5d22'; g.fillRect(0, Y(0.107), cw, Y(0.012));
  // kerb band
  g.fillStyle = '#8f9294'; g.fillRect(0, Y(0.836), cw, Y(0.012));
  g.fillStyle = '#d9d4c8'; g.fillRect(0, Y(0.848), cw, Y(0.152));
  g.fillStyle = '#bdb8ab'; g.fillRect(0, Y(0.952), cw, Y(0.048));

  // dark slate couch / shadow behind character
  g.fillStyle = '#4a5666';
  g.beginPath(); g.moveTo(X(0.20), Y(0.83)); g.lineTo(X(0.27), Y(0.55));
  g.lineTo(X(0.33), Y(0.57)); g.lineTo(X(0.28), Y(0.83)); g.closePath(); g.fill();

  // character
  g.fillStyle = '#1c1c1c';
  g.beginPath(); g.ellipse(X(0.40), Y(0.33), X(0.135), Y(0.165), 0, 0, Math.PI * 2); g.fill();
  g.fillStyle = '#efb3c4';
  g.beginPath(); g.ellipse(X(0.405), Y(0.355), X(0.098), Y(0.125), 0, 0, Math.PI * 2); g.fill();
  g.fillStyle = '#1c1c1c';
  g.beginPath(); g.ellipse(X(0.40), Y(0.262), X(0.125), Y(0.072), 0, 0, Math.PI * 2); g.fill();
  g.strokeStyle = '#1c1c1c'; g.lineWidth = 3;
  g.beginPath(); g.ellipse(X(0.372), Y(0.345), X(0.024), Y(0.032), 0, 0, Math.PI * 2); g.stroke();
  g.beginPath(); g.ellipse(X(0.442), Y(0.345), X(0.024), Y(0.032), 0, 0, Math.PI * 2); g.stroke();
  g.fillStyle = '#1c1c1c';
  g.beginPath(); g.arc(X(0.372), Y(0.352), 4.5, 0, Math.PI * 2); g.fill();
  g.beginPath(); g.arc(X(0.442), Y(0.352), 4.5, 0, Math.PI * 2); g.fill();
  g.beginPath(); g.moveTo(X(0.385), Y(0.417)); g.quadraticCurveTo(X(0.41), Y(0.437), X(0.437), Y(0.414)); g.stroke();

  // yellow shirt
  g.fillStyle = '#e8b81f';
  g.beginPath();
  g.moveTo(X(0.295), Y(0.505)); g.quadraticCurveTo(X(0.405), Y(0.44), X(0.525), Y(0.505));
  g.lineTo(X(0.555), Y(0.79)); g.lineTo(X(0.275), Y(0.79)); g.closePath(); g.fill();
  // bow at chest
  g.strokeStyle = '#1c1c1c'; g.lineWidth = 4;
  for (let i = 0; i < 7; i++) {
    const a = i * Math.PI / 3.5;
    g.beginPath(); g.moveTo(X(0.412), Y(0.565));
    g.lineTo(X(0.412) + Math.cos(a) * X(0.05), Y(0.565) + Math.sin(a) * Y(0.055)); g.stroke();
  }
  // lilac arms + shorts
  g.fillStyle = '#c9a8d4';
  g.beginPath(); g.ellipse(X(0.298), Y(0.625), X(0.045), Y(0.115), 0.35, 0, Math.PI * 2); g.fill();
  g.beginPath(); g.ellipse(X(0.548), Y(0.60), X(0.042), Y(0.105), -0.35, 0, Math.PI * 2); g.fill();
  g.fillRect(X(0.285), Y(0.765), X(0.27), Y(0.085));
  // pink heart on shirt
  g.fillStyle = '#efb3c4';
  g.beginPath(); g.arc(X(0.455), Y(0.665), X(0.028), 0, Math.PI * 2); g.fill();
  g.beginPath(); g.arc(X(0.505), Y(0.665), X(0.028), 0, Math.PI * 2); g.fill();
  g.beginPath(); g.moveTo(X(0.43), Y(0.675)); g.lineTo(X(0.48), Y(0.745)); g.lineTo(X(0.53), Y(0.675)); g.closePath(); g.fill();

  // white sign with red lettering
  g.save(); g.translate(X(0.705), Y(0.50)); g.rotate(-0.07);
  g.fillStyle = '#f2f2f2'; g.fillRect(-X(0.12), -Y(0.215), X(0.24), Y(0.43));
  g.strokeStyle = '#1c1c1c'; g.lineWidth = 3; g.strokeRect(-X(0.12), -Y(0.215), X(0.24), Y(0.43));
  g.fillStyle = '#e03c3c'; g.textAlign = 'center';
  g.font = 'bold 27px sans-serif'; g.fillText('GIVE', 0, -Y(0.115));
  g.font = 'bold 25px sans-serif'; g.fillText('PEACE', 0, -Y(0.035));
  g.font = 'bold 25px sans-serif'; g.fillText('A', 0, Y(0.045));
  g.font = 'bold 23px sans-serif'; g.fillText('CHANCE', 0, Y(0.125));
  g.restore();

  // red graffiti, left
  g.save(); g.translate(X(0.075), Y(0.60)); g.rotate(-1.18);
  g.fillStyle = '#e03c3c'; g.font = 'bold 26px sans-serif'; g.textAlign = 'center';
  g.fillText('FOR ALL KIDS', 0, 0); g.restore();
  g.strokeStyle = '#e03c3c'; g.lineWidth = 5;
  g.beginPath(); g.moveTo(X(0.015), Y(0.35)); g.lineTo(X(0.085), Y(0.43));
  g.lineTo(X(0.025), Y(0.49)); g.lineTo(X(0.08), Y(0.55)); g.stroke();

  // purple dots + tags, right
  g.fillStyle = '#43417a';
  [[0.60, 0.215], [0.645, 0.265], [0.70, 0.205], [0.755, 0.255], [0.815, 0.215], [0.86, 0.295], [0.905, 0.235], [0.785, 0.325]]
    .forEach(([u, v], i) => { g.beginPath(); g.arc(X(u), Y(v), 8 + (i % 3) * 3, 0, Math.PI * 2); g.fill(); });
  g.fillStyle = '#8fb8d8'; g.fillRect(X(0.925), Y(0.30), X(0.062), Y(0.28));
  g.strokeStyle = '#4f9d3a'; g.lineWidth = 4;
  g.beginPath(); g.moveTo(X(0.855), Y(0.43)); g.lineTo(X(0.895), Y(0.365)); g.lineTo(X(0.885), Y(0.465)); g.stroke();
  g.strokeStyle = '#2b2b2b'; g.lineWidth = 4;
  g.beginPath(); g.moveTo(X(0.955), Y(0.70)); g.lineTo(X(0.99), Y(0.66)); g.stroke();

  const tex = new THREE.CanvasTexture(cv);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.minFilter = THREE.LinearFilter;
  tex.magFilter = THREE.LinearFilter;
  return tex;
}
const MURAL = makeMural();

/* ── scene graph ────────────────────────────────────────────────────────── */
const group = new THREE.Group();
group.rotation.y = PSI;
scene.add(group);

const border = new THREE.Mesh(
  new THREE.PlaneGeometry(PW + 0.05, PH + 0.05),
  new THREE.MeshBasicMaterial({ color: 0x111111, transparent: true, depthTest: false, side: THREE.DoubleSide })
);
border.position.z = -0.03; border.renderOrder = 0;
group.add(border);

const dyn = new THREE.Group();
group.add(dyn);

/* ── state ──────────────────────────────────────────────────────────────── */
const state = {
  k: 1, offTarget: 0, offAmt: 0,
  gapTarget: 0, gapAmt: 0,
  original: true, sel: null, neighbour: true, seams: true
};
let tileRects = [];

function clearDyn() {
  for (let i = dyn.children.length - 1; i >= 0; i--) {
    const o = dyn.children[i];
    o.geometry?.dispose?.();
    if (Array.isArray(o.material)) o.material.forEach(m => m.dispose()); else o.material?.dispose?.();
    dyn.remove(o);
  }
}

function boundaries(k, t) {
  const a = [];
  for (let i = 0; i <= k + 1; i++) a.push(Math.min(1, Math.max(0, (i - 0.5 * t) / k)));
  return a;
}

function lx(u) { return (u - 0.5) * PW; }
function ly(v) { return (v - 0.5) * PH; }

function addLines(pts, color, opacity, order, dashed) {
  if (!pts.length) return;
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color, transparent: true, opacity, depthTest: false, dashSize: 0.07, gapSize: 0.05 })
    : new THREE.LineBasicMaterial({ color, transparent: true, opacity, depthTest: false });
  const ln = new THREE.LineSegments(geo, mat);
  if (dashed) ln.computeLineDistances();
  ln.renderOrder = order;
  dyn.add(ln);
  return ln;
}

function tokensIn(r) {
  const out = [];
  for (let a = 0; a < NTOK; a++) {
    const u = (a + 0.5) / NTOK;
    if (u <= r.u0 || u >= r.u1) continue;
    for (let b = 0; b < NTOK; b++) {
      const v = (b + 0.5) / NTOK;
      if (v <= r.v0 || v >= r.v1) continue;
      out.push([u, v]);
    }
  }
  return out;
}

function attentionPts(r) {
  const tk = tokensIn(r); const pts = [];
  for (let i = 0; i < tk.length; i++)
    for (let j = i + 1; j < tk.length; j++)
      pts.push(new THREE.Vector3(lx(tk[i][0]), ly(tk[i][1]), 0.05),
        new THREE.Vector3(lx(tk[j][0]), ly(tk[j][1]), 0.05));
  return pts;
}

/* ── build ──────────────────────────────────────────────────────────────── */
function rebuild() {
  clearDyn();
  const k = state.k, t = state.offAmt;
  const b = boundaries(k, t);
  const gu = GAP_U * state.gapAmt, gv = GAP_V * state.gapAmt;

  tileRects = [];
  for (let i = 0; i <= k; i++) {
    let u0 = b[i], u1 = b[i + 1];
    if (u1 - u0 < 1e-4) continue;
    const cu0 = u0 + (u0 > 0 ? gu / 2 : 0), cu1 = u1 - (u1 < 1 ? gu / 2 : 0);
    for (let j = 0; j <= k; j++) {
      let v0 = b[j], v1 = b[j + 1];
      if (v1 - v0 < 1e-4) continue;
      const cv0 = v0 + (v0 > 0 ? gv / 2 : 0), cv1 = v1 - (v1 < 1 ? gv / 2 : 0);
      tileRects.push({ i, j, u0: cu0, u1: cu1, v0: cv0, v1: cv1 });
    }
  }

  const sel = state.sel && tileRects.find(r => r.i === state.sel.i && r.j === state.sel.j);
  let nb = null;
  if (sel && state.neighbour && tileRects.length > 1) {
    nb = tileRects.find(r => r.i === sel.i + 1 && r.j === sel.j)
      || tileRects.find(r => r.i === sel.i - 1 && r.j === sel.j)
      || tileRects.find(r => r.j === sel.j + 1 && r.i === sel.i)
      || tileRects.find(r => r.j === sel.j - 1 && r.i === sel.i);
  }

  // accent frames (behind tiles)
  const frame = (r, col) => {
    const m = new THREE.Mesh(
      new THREE.PlaneGeometry((r.u1 - r.u0) * PW + 0.075, (r.v1 - r.v0) * PH + 0.075),
      new THREE.MeshBasicMaterial({ color: col, transparent: true, depthTest: false, side: THREE.DoubleSide }));
    m.position.set(lx((r.u0 + r.u1) / 2), ly((r.v0 + r.v1) / 2), 0.005);
    m.renderOrder = 1; dyn.add(m);
  };
  if (sel) frame(sel, 0xff9d2e);
  if (nb) frame(nb, 0x2e8bff);

  // tiles
  const gridPts = [], outPts = [];
  for (const r of tileRects) {
    const dim = sel && !(r === sel || r === nb);
    const mat = new THREE.MeshBasicMaterial({
      map: MURAL, transparent: true, opacity: dim ? 0.45 : 1.0,
      depthTest: false, side: THREE.DoubleSide
    });
    const geo = new THREE.PlaneGeometry((r.u1 - r.u0) * PW, (r.v1 - r.v0) * PH);
    const uv = geo.attributes.uv;
    uv.setXY(0, r.u0, r.v1); uv.setXY(1, r.u1, r.v1);
    uv.setXY(2, r.u0, r.v0); uv.setXY(3, r.u1, r.v0);
    uv.needsUpdate = true;
    const m = new THREE.Mesh(geo, mat);
    m.position.set(lx((r.u0 + r.u1) / 2), ly((r.v0 + r.v1) / 2), 0.01);
    m.renderOrder = 2;
    dyn.add(m);

    // token grid clipped to this tile
    for (let n = 1; n < NTOK; n++) {
      const u = n / NTOK;
      if (u > r.u0 + 1e-5 && u < r.u1 - 1e-5)
        gridPts.push(new THREE.Vector3(lx(u), ly(r.v0), 0.03), new THREE.Vector3(lx(u), ly(r.v1), 0.03));
      const v = n / NTOK;
      if (v > r.v0 + 1e-5 && v < r.v1 - 1e-5)
        gridPts.push(new THREE.Vector3(lx(r.u0), ly(v), 0.03), new THREE.Vector3(lx(r.u1), ly(v), 0.03));
    }
    const c = [[r.u0, r.v0], [r.u1, r.v0], [r.u1, r.v1], [r.u0, r.v1]];
    for (let n = 0; n < 4; n++) {
      const p = c[n], q = c[(n + 1) % 4];
      outPts.push(new THREE.Vector3(lx(p[0]), ly(p[1]), 0.032), new THREE.Vector3(lx(q[0]), ly(q[1]), 0.032));
    }
  }
  addLines(gridPts, 0x3a3a3a, 0.75, 3, false);
  addLines(outPts, 0x2a2a2a, 0.95, 3, false);

  // dashed markers on the regular (unshifted) seams
  if (state.seams && k > 1 && !state.original) {
    const sp = [];
    for (let n = 1; n < k; n++) {
      const u = n / k, v = n / k;
      sp.push(new THREE.Vector3(lx(u), ly(0), 0.04), new THREE.Vector3(lx(u), ly(1), 0.04));
      sp.push(new THREE.Vector3(lx(0), ly(v), 0.04), new THREE.Vector3(lx(1), ly(v), 0.04));
    }
    addLines(sp, 0xc03cc0, 0.9, 4, true);
  }

  // attention lines
  if (sel) addLines(attentionPts(sel), 0xff9d2e, 0.38, 5, false);
  if (nb) addLines(attentionPts(nb), 0x2e8bff, 0.32, 5, false);

  refreshLabels();
}

/* ── camera (oblique = cabinet shear done by the scaffold) ──────────────── */
rebuild();
setCameraView({
  projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5,
  axisScreenAngles: null, heightFraction: 0.68
});

/* ── labels ─────────────────────────────────────────────────────────────── */
const wp = (u, v) => group.localToWorld(new THREE.Vector3(lx(u), ly(v), 0));
const letterLbl = addLabel('a)', wp(-0.03, 1.12), { fontSize: '19px', bold: true, color: '#222' });
const captionLbl = addLabel('Original<br>image', wp(0.5, -0.25), { fontSize: '15px', color: '#222' });

function panelInfo() {
  if (state.original) return { letter: 'a)', cap: 'Original<br>image' };
  const off = state.offTarget > 0.5;
  if (state.k === 1) return { letter: 'f)', cap: '1×1 window' };
  if (state.k === 2) return off ? { letter: 'e)', cap: '2×2 offset<br>windows' } : { letter: 'd)', cap: '2×2 windows' };
  return off ? { letter: 'c)', cap: '4×4 offset<br>windows' } : { letter: 'b)', cap: '4×4 windows' };
}
function refreshLabels() {
  const p = panelInfo();
  letterLbl.div.innerHTML = p.letter;
  captionLbl.div.innerHTML = p.cap;
}
refreshLabels();

/* ── picking (screen-space, exact under the oblique shear) ──────────────── */
const _pv = new THREE.Vector3();
function proj(u, v) {
  _pv.set(lx(u), ly(v), 0.01);
  group.localToWorld(_pv);
  _pv.project(camera);
  return { x: _pv.x, y: _pv.y };
}
function sideSign(a, b, p) { return (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x); }
function inQuad(p, a, b, c, d) {
  const s1 = sideSign(a, b, p), s2 = sideSign(b, c, p), s3 = sideSign(c, d, p), s4 = sideSign(d, a, p);
  return (s1 >= 0 && s2 >= 0 && s3 >= 0 && s4 >= 0) || (s1 <= 0 && s2 <= 0 && s3 <= 0 && s4 <= 0);
}
function pickTile(ev) {
  const r = canvas.getBoundingClientRect();
  const p = { x: ((ev.clientX - r.left) / r.width) * 2 - 1, y: -((ev.clientY - r.top) / r.height) * 2 + 1 };
  for (const t of tileRects) {
    if (inQuad(p, proj(t.u0, t.v0), proj(t.u1, t.v0), proj(t.u1, t.v1), proj(t.u0, t.v1))) return t;
  }
  return null;
}

let _dx = 0, _dy = 0;
canvas.addEventListener('pointerdown', e => { _dx = e.clientX; _dy = e.clientY; });
canvas.addEventListener('click', e => {
  if (Math.abs(e.clientX - _dx) + Math.abs(e.clientY - _dy) > 6) return;
  const t = pickTile(e);
  state.sel = t ? { i: t.i, j: t.j } : null;
  rebuild();
});
canvas.addEventListener('pointermove', e => {
  const t = pickTile(e);
  if (t) {
    canvas.style.cursor = 'pointer';
    const n = tokensIn(t).length;
    showTooltip(`Window tile — ${n} token${n === 1 ? '' : 's'}; click for its self-attention`, e);
  }
});

/* ── controls ───────────────────────────────────────────────────────────── */
const elK = document.getElementById('windowSize');
const elKv = document.getElementById('wsVal');
const btnReg = document.getElementById('btnRegular');
const btnOff = document.getElementById('btnOffset');
const chkNb = document.getElementById('chkNeighbour');
const chkSe = document.getElementById('chkSeams');
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

function syncUI() {
  elK.value = String(state.k);
  elKv.textContent = state.k;
  const off = state.offTarget > 0.5;
  btnReg.classList.toggle('active', !off);
  btnOff.classList.toggle('active', off);
  btnOff.disabled = (state.k === 1);
  btnOff.style.opacity = (state.k === 1) ? 0.45 : 1;
  chkNb.checked = state.neighbour;
  chkSe.checked = state.seams;
}

let prevK = 1;
elK.addEventListener('input', () => {
  let v = parseInt(elK.value, 10);
  if (v === 3) v = (prevK === 2) ? 4 : 2;
  prevK = v;
  if (v !== state.k) { state.sel = null; }
  state.k = v;
  state.original = false;
  state.gapTarget = 1;
  if (v === 1) state.offTarget = 0;
  syncUI(); rebuild();
});
btnReg.addEventListener('click', () => { state.offTarget = 0; state.original = false; state.gapTarget = 1; syncUI(); });
btnOff.addEventListener('click', () => { if (state.k === 1) return; state.offTarget = 1; state.original = false; state.gapTarget = 1; syncUI(); });
chkNb.addEventListener('change', () => { state.neighbour = chkNb.checked; rebuild(); });
chkSe.addEventListener('change', () => { state.seams = chkSe.checked; rebuild(); });
document.getElementById('btnClearSel').addEventListener('click', () => { state.sel = null; rebuild(); });

/* ── guided tour ────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'a) Original image', text: 'The full photograph, uncut, with its fine token grid: every patch is a token that could in principle attend to every other.', k: 1, off: 0, original: true, sel: null },
  { title: 'f) 1×1 window', text: 'With a single window, attention is global — one tile holds all 64 tokens. The dense all-to-all connections show the quadratic cost.', k: 1, off: 0, original: false, sel: { i: 0, j: 0 } },
  { title: 'd) 2×2 windows', text: 'The image splits into four windows separated by white gaps. Attention runs only within each quadrant; tokens either side of a gap cannot talk.', k: 2, off: 0, original: false, sel: { i: 1, j: 1 } },
  { title: 'e) 2×2 offset windows', text: 'Shifting the same lattice by half a window re-partitions the image: tokens split by the dashed central seam now sit together, so the next layer mixes across the old borders.', k: 2, off: 1, original: false, sel: { i: 1, j: 1 } },
  { title: 'b) 4×4 windows', text: 'Sixteen small windows: attention is highly local and cheap, but each token sees only a 2×2 token neighbourhood.', k: 4, off: 0, original: false, sel: { i: 2, j: 2 } },
  { title: 'c) 4×4 offset windows', text: 'The offset 4×4 grid leaves half-width strips at the edges and re-couples every boundary pair — alternating b) and c) across layers propagates information globally without global attention.', k: 4, off: 1, original: false, sel: { i: 2, j: 2 } }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  state.k = s.k; prevK = s.k;
  state.offTarget = s.off;
  state.original = s.original;
  state.gapTarget = s.original ? 0 : 1;
  state.sel = s.sel ? { ...s.sel } : null;
  stepTitle.textContent = s.title;
  stepText.textContent = s.text;
  syncUI(); rebuild();
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── animation of the partition transitions ─────────────────────────────── */
function tick() {
  requestAnimationFrame(tick);
  let dirty = false;
  if (Math.abs(state.offAmt - state.offTarget) > 0.002) {
    state.offAmt += (state.offTarget - state.offAmt) * 0.16; dirty = true;
  } else if (state.offAmt !== state.offTarget) { state.offAmt = state.offTarget; dirty = true; }
  if (Math.abs(state.gapAmt - state.gapTarget) > 0.002) {
    state.gapAmt += (state.gapTarget - state.gapAmt) * 0.18; dirty = true;
  } else if (state.gapAmt !== state.gapTarget) { state.gapAmt = state.gapTarget; dirty = true; }
  if (dirty) rebuild();
}
tick();

goToStep(0);
